            //
            aOrbiterI = (((aOrbiterI + aOrbiterJ) + 0x8123D5391930EEAEULL) + aSeedOrbiterUpdateSaltF[(((31U - aIndex) + 14U)) & S_SALT1]) + aNonceWordB;
