            aOrbiterA = (((aWandererI + RotL64(aPrevious, 27U)) + RotL64(aCarry, 5U)) + 0x782125A8FEAE5B05ULL) + aTwistOrbiterAssignSaltC[((aIndex + 9U)) & S_SALT1];
