            aOrbiterH = ((aWandererE + RotL64(aPrevious, 51U)) + RotL64(aCarry, 5U)) + 0x7DD5E6248CEF30AAULL;
            aOrbiterJ = (aWandererH + RotL64(aCross, 3U)) + 0x12E26E0E1BF96AB2ULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 14U)) + 0x6614B9028853070CULL;
            aOrbiterC = (aWandererD + RotL64(aScatter, 27U)) + 0x927923254B2D1138ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x3C399608ED2AE435ULL;
