            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xFE8E7267658C443AULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x31D79DCCC8CF8FD3ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 13U)) & S_SALT1];
