            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0xAA60D4CDDEE16F67ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x67AB1CB06EA53E1EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xEDD8744D5D1972BDULL), 27U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0xD3662E1BB568571DULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xD131C4BAD859E35DULL;
            aOrbiterF = RotL64((aOrbiterF * 0x92D633EC90DD20DFULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x1CB0A21FD207616AULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x78731A11B0AFBCA5ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x833B0D32CE19C6C5ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x478C9901BF121BEBULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x5FD42BE9039A76B6ULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x7AFA3173CECA2BE1ULL), 35U);
            //
            aIngress = RotL64(aOrbiterE, 37U) ^ aOrbiterA;
            aIngress = aIngress + (RotL64(aOrbiterC, 53U) ^ aOrbiterF);
            aIngress = aIngress + (RotL64(aOrbiterG, 21U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterJ, 43U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererD = aWandererD + ((RotL64(aPrevious, 53U) + RotL64(aOrbiterJ, 51U)) + aOrbiterF);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 39U) + RotL64(aOrbiterG, 37U)) + aOrbiterE);
            aWandererF = aWandererF + (((RotL64(aIngress, 11U) + RotL64(aOrbiterA, 13U)) + aOrbiterH) + RotL64(aCarry, 43U));
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 26U) + RotL64(aOrbiterC, 3U)) + aOrbiterH);
            aWandererE = aWandererE + ((((RotL64(aScatter, 19U) + aOrbiterG) + RotL64(aOrbiterH, 21U)) + RotL64(aCarry, 23U)) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererH = aWandererH ^ (((RotL64(aPrevious, 47U) + RotL64(aOrbiterC, 58U)) + aOrbiterE) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 21U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aIngress, 5U) + aOrbiterG) + RotL64(aOrbiterJ, 43U));
