            aOrbiterG = (aWandererE + RotL64(aScatter, 60U)) + 0xCA6DAA5DBE777415ULL;
            aOrbiterB = (aWandererK + RotL64(aIngress, 5U)) + 0x96A1F488825F5AABULL;
            aOrbiterI = ((aWandererI + RotL64(aPrevious, 27U)) + RotL64(aCarry, 53U)) + 0x4AD448CA75FD69C3ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 47U)) + RotL64(aCarry, 35U)) + 0xCD259E4853C6B063ULL;
            aOrbiterA = ((aWandererB + RotL64(aIngress, 53U)) + RotL64(aCarry, 11U)) + 0x9E22CE1C7D412DCAULL;
            aOrbiterD = ((aWandererF + RotL64(aScatter, 11U)) + 0x504C5B76183292DFULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aCross, 39U)) + 0x0859ADEC0F40CD1EULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xDEA1F2EBB521F4DCULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0xD8AF1D520C9B14C5ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x196F65E7F53A979BULL), 47U);
