            aOrbiterJ = RotL64((aOrbiterJ * 0xBF109E8E61DCAD8DULL), 5U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x81A380D195BEDC65ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x28F5CC182BEC9A60ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1304571326D185C3ULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xE6F08FD40B96F4F9ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x5D29E9953EC845A6ULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 19U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xAA5F4912214A1525ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xE622B9C637ED01FAULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x7316A60E55D46E76ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xA65F6DD5F059F323ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0xDB94ABBDBA94BB1BULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x2BD0A37B6463D85EULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x4C4130D1C60D2929ULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x29977EEBD2777E27ULL;
