            aWandererI = aWandererI ^ (((RotL64(aPrevious, 43U) + aOrbiterD) + RotL64(aOrbiterJ, 47U)) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 60U) + aOrbiterK) + RotL64(aOrbiterB, 27U)) + aKeyRotateWandererUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1]);
