            aCross ^= (RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 3430U)) & S_BLOCK1], 4U) ^ RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 1921U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 26U) + RotL64(aCross, 13U)) ^ (RotL64(aPrevious, 51U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterB = (aWandererI + RotL64(aCross, 54U)) + 0x9C4DBD7076901AF9ULL;
            aOrbiterA = (aWandererD + RotL64(aIngress, 47U)) + 0x41416C6167C8EF43ULL;
            aOrbiterD = ((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 3U)) + 0xB5573D0338AA0E4FULL;
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 19U)) + RotL64(aCarry, 21U)) + 0xA3C64E9F7EE79D38ULL;
            aOrbiterF = (aWandererE + RotL64(aCross, 10U)) + 0x7B38F2E8DC04367BULL;
            aOrbiterI = (aWandererH + RotL64(aIngress, 5U)) + 0x590739F51F58FA6EULL;
