            aOrbiterA = (((aWandererH + RotL64(aScatter, 3U)) + RotL64(aCarry, 29U)) + 0x924207ACB4273418ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
