            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x8B91FA829A65CB33ULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
