            aCross ^= (RotL64(aSpiritLaneB[((S_BLOCK1 - aIndex + 12630U)) & S_BLOCK1], 53U) ^ RotL64(aKineticLaneA[((S_BLOCK1 - aIndex + 8840U)) & S_BLOCK1], 39U));
