            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0xF98AAECD618C0A2CULL) ^ aKeySpawnOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x0DB340E41D43D5B1ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0xD70AF2072C4ACD78ULL) + aKeySpawnOrbiterUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xB8BD9F63E8A4D920ULL;
